{
  "references": [
    {
      "id": "R1",
      "summary_ko": "프롬프트에 지정되지 않은 일종의 우주선이 하늘에 보임."
    },
    {
      "id": "R2",
      "summary_ko": "얼굴들이 다소 기괴하고 부자연스럽게 움직임."
    },
    {
      "id": "R3",
      "summary_ko": "화면 좌측 상단에서 중앙 상단 쪽으로 날아가던 드론이 사라짐."
    },
    {
      "id": "R4",
      "summary_ko": "배경에서 가방을 들고 가던 사람이 가려졌다가 시야가 확보되었을 때 완전히 사라짐."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "좌측 상단 하늘의 작은 비행 물체가 형태를 바꾸며 하늘에서 갑자기 사라짐."
    },
    {
      "id": "C2",
      "summary_ko": "좌측 상단의 작은 비행 물체가 형태를 바꾸며 사라짐."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 하늘에 우주선이 나타나는 현상을 지적하지만, C1은 비행 물체가 변형되며 사라지는 결함을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 하늘에 원치 않는 우주선이 보이는 것에 대한 설명이며, C2는 비행 물체의 변형 및 소멸을 지적하므로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R2는 사람의 얼굴 변형 및 움직임에 관한 것이고, C1은 하늘의 비행 물체 소멸에 관한 것입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 사람 얼굴의 부자연스러움을 설명하고 있으며, C2는 하늘의 비행 물체에 관한 내용입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "화면 좌측 상단 하늘을 날아가던 비행 물체(드론)가 갑자기 사라지는 동일한 결함을 설명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "좌측 상단 하늘의 비행 물체(드론)가 사라지는 현상을 가리키므로 동일한 현상에 대한 설명입니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R4는 배경에 있는 사람의 불연속적인 실종을 다루며, C1은 하늘의 비행 물체 소멸을 다룹니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R4는 배경 속 인물의 소멸에 관한 것이고, C2는 하늘에 있는 비행 물체의 형태 변화 및 소멸에 관한 것입니다."
    }
  ]
}
